 reviews.append(dict(url=r['url'],page_type=r['pageType'],prior35_4=f['prior_35_4_change'],source=r['source'],question_1_user_task=d.get('decisionJourney',{}).get('primaryQuestion') or d.get('description') or r['title'],question_2_beyond_vendor_excerpt=specific,question_3_editorial_analysis_excerpt=actual(r,'comparisons') if r['evidenceCandidates']['comparisons'] else actual(r),question_4_verifiability='Vorhandene sichtbare Quellenkandidaten: '+str(f['documented_source_links'])+'; Feldquellen: '+str(f['registered_source_count'])+'. Kein frischer vollständiger Faktencheck. '+ ('Eigener Praxistest nicht dokumentiert.' if r['pageType']=='product' else 'Aussagen-/Rechenbeispiele sind von medizinischen oder experimentellen Belegen zu unterscheiden.'),source_urls=r['evidenceCandidates']['sourceLinks']+[s.get('url') for s in d.get('evidenceSources',[]) if isinstance(s,dict) and s.get('url')],question_5_decision_excerpt=excerpt(d.get('recommendation','')) or actual(r),question_6_related_candidate=f['most_similar_related_url'],related_lexical_cosine=f['max_related_tfidf_cosine'],concrete_review=concern,assessment='Manual targeted finding' if r['url'] in gaps or r['route'] in ['/produkt/petlibro-granary-dual-feeder/','/hersteller/petkit/','/vergleiche/beste-trinkbrunnen-fuer-hunde/'] else 'Structured text-based screening; no automatic quality grade'))
